package com.masaakis.order.api;import com.masaakis.order.application.OrderEventStream;import com.masaakis.security.StaffPrincipal;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;
@RestController@RequestMapping("/api/admin/order-events")public class OrderEventController{private final OrderEventStream events;public OrderEventController(OrderEventStream e){events=e;}@GetMapping SseEmitter stream(@AuthenticationPrincipal StaffPrincipal p){return events.subscribe(p);}}
